"""Curated disease guidance. Product rates must be checked against the product label."""
HEALTHY = dict(description='The inspected leaf shows no visible disease symptoms.', general_measures='Continue regular scouting, balanced nutrition, clean tools, and irrigation that keeps foliage dry.', chemical_treatment='No chemical treatment is needed.', products=[dict(name='Balanced NPK fertiliser', type='Fertiliser', use='Apply only according to a soil test and crop stage; do not overapply nitrogen.')])

def entry(name, pathogen, symptoms, severity, description, measures, chemical, products):
    return dict(name=name, pathogen=pathogen, symptoms=symptoms, severity=severity, description=description,
                general_measures=measures, chemical_treatment=chemical, products=products,
                treatment=chemical, prevention=measures, organic_treatment='Use approved biocontrols where locally available.')

DISEASE_DATABASE = {
 'Tomato': [entry('Early Blight', 'Alternaria solani', 'Dark concentric spots, usually on older leaves.', 'Medium', 'A fungal leaf disease that can reduce foliage and fruit yield.', 'Remove affected leaves, rotate crops, mulch soil, and avoid wet foliage.', 'Use a protectant fungicide before disease spreads; follow the label interval.', [dict(name='Mancozeb', type='Fungicide', use='Spray a labelled formulation when first spots appear; repeat only as label permits.'), dict(name='Copper fungicide', type='Fungicide', use='Use as an alternative protectant in a rotation program.')]), entry('Late Blight', 'Phytophthora infestans', 'Water-soaked lesions and white growth beneath leaves.', 'High', 'A fast-spreading water-mould disease that can destroy tomato plants.', 'Remove severely affected plants, improve drainage, and avoid overhead irrigation.', 'Apply a locally registered late-blight fungicide promptly and rotate modes of action.', [dict(name='Metalaxyl + Mancozeb', type='Fungicide', use='Apply at first warning signs under label directions; do not use repeatedly without rotation.'), dict(name='Copper fungicide', type='Fungicide', use='Use preventively during suitable weather if approved for the crop.')]), entry('Leaf Curl Virus', 'Tomato yellow leaf curl virus', 'Upward leaf curl, yellowing, and stunted growth.', 'High', 'A viral disease transmitted mainly by whiteflies; infected plants do not recover.', 'Remove infected plants, use clean seedlings, insect netting, reflective mulch, and monitor whiteflies.', 'There is no curative chemical treatment; manage the insect vector only.', [dict(name='Yellow sticky traps', type='Monitoring product', use='Install early and inspect weekly to detect and reduce adult whiteflies.'), dict(name='Neem-based insecticide', type='Insecticide', use='Use against young whitefly stages as labelled; cover leaf undersides.')])],
 'Rice': [entry('Rice Blast', 'Magnaporthe oryzae', 'Diamond-shaped lesions with grey centres.', 'High', 'A fungal disease that attacks leaves and panicles, especially in humid fields.', 'Use clean seed, resistant varieties, balanced nitrogen, and good field sanitation.', 'Use a registered blast fungicide at early symptoms or according to local advisory.', [dict(name='Tricyclazole', type='Fungicide', use='Apply only at the registered crop stage and label rate.'), dict(name='Silicon fertiliser', type='Fertiliser', use='Use as part of nutrient management to strengthen rice plants.')]), entry('Brown Spot', 'Bipolaris oryzae', 'Oval brown leaf spots with yellow halos.', 'Medium', 'A fungal disease often made worse by nutrient stress and poor seed health.', 'Use treated seed, balanced nutrients, and avoid drought stress.', 'Use a registered protectant fungicide when disease is spreading.', [dict(name='Mancozeb', type='Fungicide', use='Apply as labelled when symptoms begin and conditions remain favourable.'), dict(name='Trichoderma seed treatment', type='Biocontrol', use='Treat seed before sowing according to product instructions.')])],
 'Wheat': [entry('Yellow Rust', 'Puccinia striiformis', 'Yellow-orange pustules arranged in stripes.', 'High', 'A fungal rust that spreads rapidly in cool, humid weather.', 'Plant resistant varieties, remove volunteer wheat, and scout fields weekly.', 'Apply a registered triazole fungicide at first confirmed infection.', [dict(name='Propiconazole 25 EC', type='Fungicide', use='Use at the product-label rate when rust is first observed; observe pre-harvest limits.')]), entry('Powdery Mildew', 'Blumeria graminis', 'White powdery coating on leaves and stems.', 'Medium', 'A fungal disease that thrives in dense, lush crop canopies.', 'Avoid excess nitrogen, improve airflow, and use tolerant varieties.', 'Apply a registered sulphur or systemic fungicide if disease increases.', [dict(name='Wettable sulphur', type='Fungicide', use='Apply in suitable temperatures as directed on the label.')])],
 'Maize': [entry('Northern Leaf Blight', 'Exserohilum turcicum', 'Long grey-green leaf lesions.', 'Medium', 'A fungal leaf blight that reduces photosynthesis and grain fill.', 'Rotate crops, remove crop residue where practical, and grow resistant hybrids.', 'Use a registered foliar fungicide if disease reaches damaging levels.', [dict(name='Azoxystrobin', type='Fungicide', use='Apply at the labelled growth stage after field scouting confirms need.')])],
 'Cotton': [entry('Bollworm Infestation', 'Helicoverpa armigera', 'Damaged flowers and bolls with frass.', 'High', 'A caterpillar pest that feeds inside squares and bolls.', 'Use pheromone traps, conserve beneficial insects, remove infested plant parts, and avoid repeated insecticide groups.', 'Treat only when local economic threshold is reached; rotate insecticide modes of action.', [dict(name='Spinosad', type='Insecticide', use='Spray young larvae at the label rate after monitoring confirms threshold.'), dict(name='Pheromone traps', type='Monitoring product', use='Install before flowering and check regularly to guide treatment timing.')])]
}
for entries in DISEASE_DATABASE.values():
    entries.append(dict(name='Healthy', pathogen='None', symptoms='No disease symptoms detected.', severity='None', treatment='No treatment needed.', prevention='Maintain routine scouting and crop hygiene.', organic_treatment='Not applicable.', **HEALTHY))
